import os
import socket
import time
import re

import Pyro4
import Pyro4.util
from hran_elementmanager2g import ssh_client
from hran_elementmanager2g.utils.loggers import logger


class ElementManagerClient(object):
    SERVER_FILE_NAME = "pyro_server"
    TRACES_SERVER_FILE_NAME = "pyro_server_traces"
    library_name = 'hran_elementmanager2g'

    def __init__(self, element_manager_pc_ip, ssh_user, ssh_password, pyro_port, pyro_server_name, bts_host, bts_port,
                 bts_password, bcfnumber, remotelibpath=library_name, server_py_file_name=SERVER_FILE_NAME):
        """
        ElementManagerClient init parameters.

        :param element_manager_pc_ip:            IP address of remote Element Manager PC
        :param ssh_user:                         SSH username to Element Manager PC
        :param ssh_password:                     SSH password to Element Manager PC
        :param pyro_port:                        Port number on Element Manager PC on which Pyro Server will listen
        :param pyro_server_name                  Name of the pyro server to register URI
        :param bts_host                          2G BTS IP address to which Element Manager 2G is connecting
        :param bts_port                          2G BTS Port to which Element Manager 2G is connecting
        :param bts_password                      2G BTS Element Manager Password
        :param bcfnumber                         2G BTS BCF number
        :param remotelibpath:                    Path on Element Manager PC where files can be copied
        :param server_py_file_name               Name of the pyro server file which will run on Element Manager PC
        """
        self.connected = False
        self.pyro_client_object = None
        self.host = element_manager_pc_ip
        self.port = pyro_port
        self.pyro_server_name = pyro_server_name
        self.uri = 'PYRO:{name}@{ip}:{port}'.format(name=self.pyro_server_name, ip=self.host, port=self.port)
        self.ssh_user = str(ssh_user)
        self.ssh_password = str(ssh_password)
        self.remotelibpath = str(remotelibpath)
        if self.pyro_server_name != 'ElementManager2G_traces':
            self.server_py_file_name = str(server_py_file_name)
        else:
            self.server_py_file_name = str(self.TRACES_SERVER_FILE_NAME)
        self.bts_host = bts_host
        self.bts_port = bts_port
        self.bts_password = bts_password
        self.bcfnumber = bcfnumber

    def connect(self):

        """
         Method to start pyro server on remote host and create pyro object used by pyro client to connect.
        """

        logger.debug("connect_safe_self.server_py_file_name = " + self.server_py_file_name)
        logger.debug("start remote pyro server")
        self._start_remote_server()
        logger.debug("connect_safe _check_pyro_obj")
        self._check_pyro_obj()
        logger.debug("connect_safe connected = True")
        self.connected = True

    def is_connected(self):
        return self.connected

    def _start_remote_server(self):
        self._ensure_ssh_connected()
        if self.pyro_server_name == 'ElementManager2G':
            self.kill_residual_processes(['ipy.exe', 'ipy32.exe', 'java.exe'])
        if self.pyro_server_name == 'ElementManager2G_traces':
            self.kill_residual_processes(['tshark.exe', 'dumpcap.exe'])
        self._run_server_on_remote_machine()
        self.ssh_connection.ssh_close_connection()

    def _check_pyro_obj(self):
        """
        Method to create and set pyro client object attribute based on provided URI
        :return:  pyro client object
        """
        Pyro4.DETAILED_TRACEBACK = True
        Pyro4.config.PICKLE_PROTOCOL_VERSION = 2
        if self.pyro_client_object is None:
            with Pyro4.Proxy(self.uri) as p:
                p._pyroMaxRetries = 0
                p._pyroTimeout = 0
                p._pyroSerializer = "pickle"
                self.pyro_client_object = p
        return self.pyro_client_object

    def _ensure_ssh_connected(self):
        if not hasattr(self, "ssh_connection"):
            self.ssh_connection = ssh_client.SshClient(self.host, self.ssh_user, self.ssh_password)
        elif self.ssh_connection:
            if not self.ssh_connection.is_connected():
                self.ssh_connection = ssh_client.SshClient(self.host, self.ssh_user, self.ssh_password)

    def _run_server_on_remote_machine(self):
        wrapper_cmd = '{} {} {} {}'.format(self.bts_host, self.bts_port, self.bts_password, self.bcfnumber)
        ironpython_path = self.get_ipy_path()
        if self.pyro_server_name != 'ElementManager2G_traces':
            cmdstr = r"cmd /C {ironpython_path} -m {library_name}.{pyro_filename} {wrapper_cmd} {pyro_port}".format(
                ironpython_path=ironpython_path,
                library_name=self.library_name,
                pyro_filename=self.server_py_file_name,
                wrapper_cmd=wrapper_cmd,
                pyro_port=self.port)
        else:
            cmdstr = r"cmd /C {ironpython_path} -m {library_name}.{pyro_filename} {pyro_port}".format(
                ironpython_path=ironpython_path,
                library_name=self.library_name,
                pyro_filename=self.server_py_file_name,
                pyro_port=self.port)
        self.ssh_connection.ssh_send_command_2(cmdstr)
        self._check_stderr_on_elm_pc()

    def _check_stderr_on_elm_pc(self):
        lines = []
        for i in range(100):
            try:
                self.ssh_connection.stderr.channel.settimeout(8)
                line = self.ssh_connection.stderr.readline()
                logger.info("Received err line from Element Manager PC PC: " + line.decode('cp437'))
                lines.append(line)
            except socket.timeout:
                if len(lines) == 0:
                    return
                msg = 'fail to read err from Element Manager PC, Element Manager PC says:\n' + '\n'.join(lines)
                raise Exception(msg)
            if 'ImportError' in line:
                break
        raise Exception('fail to read from Element Manager PC, Element Manager PC says:\n' + '\n'.join(lines))

    def _check_stdout_on_elm_pc(self):
        lines = []
        logger.debug("All lines", str(lines))
        for i in range(100):
            try:
                self.ssh_connection.stdout.channel.settimeout(8)
                line = self.ssh_connection.stdout.readline()
                logger.info("Received out line from Element Manager PC: " + line.decode('cp437'))
                lines.append(line)
            except socket.timeout:
                msg = 'fail to read out from Element Manager PC, Element Manager PC says:\n' + '\n'.join(lines)
                raise Exception(msg)
            if "element_manager_pyro_server_running" in line:
                return True
        raise Exception('Fail to read from Element Manager PC, Element Manager PC says:\n' + '\n'.join(lines))

    def transfer_folder_to_remote_host(self, remote_dir, local_dir):
        self._ensure_ssh_connected()
        self.ssh_connection.transfer_folder_to_remote_ssh_host(remote_dir, local_dir)

    def transfer_file_to_remote_ssh_host(self, cwd, remote_file, local_file):
        self._ensure_ssh_connected()
        return self.ssh_connection.transfer_file_to_remote_ssh_host(cwd, remote_file, local_file)

    def transfer_file_from_remote_ssh_host(self, cwd, remote_file, local_file):
        self._ensure_ssh_connected()
        # cwd = self.pyro_client_object.convert_windows_to_cygwin_path(cwd)
        cygstring = re.sub(r"\n", "", ''.join(self.ssh_connection.ssh_send_cmd_and_return_output("cygpath \'{}\'".format(cwd))))
        return self.ssh_connection.transfer_file_from_remote_ssh_host(cygstring, remote_file, local_file)

    def _stop_remote_server(self):
        self.pyro_client_object.stop_server()
        if self.pyro_client_object is not None:
            if hasattr(self.pyro_client_object, "_pyroRelease"):
                logger.debug("_pyroRelease()")
                self.pyro_client_object._pyroRelease()

    def _disconnect_pyro_client(self):
        if self.ssh_connection is not None and self.ssh_connection.is_connected():
            self.ssh_connection.ssh_close_connection()

    def setup_log_dir(self, dirpath, rel_drive):
        self.pyro_client_object.setup_log_dir(dirpath, rel_drive)

    def check_server_pyro_version(self):
        output = self.pyro_client_object.check_server_pyro_version
        return output

    def check_client_pyro_version(self):
        cmd = 'python "import Pyro4.constants as c; print(c.PROTOCOL_VERSION)"'
        output = os.popen(cmd).read().rstrip()
        return output

    def kill_ipy_process(self):
        self.ssh_connection.ssh_kill_windows_process("ipy.exe")
        time.sleep(1)

    def kill_tshark_process(self):
        self.ssh_connection.ssh_kill_windows_process("tshark.exe")
        time.sleep(1)

    def kill_dumpcap_process(self):
        self.ssh_connection.ssh_kill_windows_process("dumpcap.exe")
        time.sleep(1)

    def kill_residual_processes(self, pattern):
        self.ssh_connection.ssh_kill_windows_processes(pattern)

    def get_ipy_path(self):
        return self.ssh_connection.ssh_get_ipy_path()
